const data = $json;

const tema = data['Tema sugerido'] || data.tema || '';
const keyword = data['Keyword sugerida'] || data.keyword || '';
const categoria = data['Categoria sugerida'] || data.categoria || '';

return [{
  json: {
    temaSugerido: String(tema).trim(),
    keywordSugerida: String(keyword).trim(),
    categoriaSugerida: String(categoria).trim(),
    hoje: new Date().toISOString().slice(0, 10),
  },
}];

const d = $json;

return [{
  json: {
    tema: d.temaSugerido,
    keyword: d.keywordSugerida || '(inferir a palavra-chave principal mais relevante a partir do tema acima)',
    categoria: d.categoriaSugerida || '(escolher a categoria mais adequada dentre as opções permitidas)',
    intencaoBusca: '(inferir a intenção de busca mais provável para esse tema)',
    hoje: d.hoje,
  },
}];

const hoje = $('Normalizar Entrada').first().json.hoje;
const recentes = ($json.data || [])
  .map((p) => (p.title && (p.title.es || p.title.pt || p.title.en)) || '')
  .filter(Boolean);

const listaRecentes = recentes.length
  ? recentes.map((t) => `- ${t}`).join('\n')
  : '(nenhum post publicado ainda)';

const instrucoes = `Pesquise na internet por notícias, tendências, mudanças legislativas recentes e dúvidas frequentes sobre controle de ponto/jornada de trabalho, gestão de RH, compliance trabalhista e produtividade, com foco em PMEs na Espanha (mercado principal) e secundariamente no Brasil. Data de hoje: ${hoje}.

NÃO repita nenhum destes temas já publicados recentemente:
${listaRecentes}

Depois de pesquisar, responda APENAS com um JSON válido, sem markdown, sem texto fora do JSON, neste formato exato:
{"tema":"","keyword":"","categoria":"","intencao_busca":"","justificativa":""}

Regras:
- categoria deve ser exatamente uma destas: produto, controle-ponto, gestao-rh, compliance, produtividade, folha-ponto.
- intencao_busca deve ser exatamente uma destas: informacional, comercial, comparativo, guia-pratico.
- tema deve ser específico e prático, não genérico, e diferente dos temas recentes listados acima.
- justificativa deve explicar em 1-2 frases por que esse tema é relevante agora, citando o contexto pesquisado.`;

return [{
  json: {
    openAiResearchRequest: {
      model: 'gpt-4o',
      tools: [{ type: 'web_search_preview' }],
      input: instrucoes,
    },
  },
}];

const resp = $json;
const output = resp.output || [];
const messageItem = output.find((o) => o.type === 'message') || {};
const textPart = (messageItem.content || []).find((c) => c.type === 'output_text') || {};
const raw = textPart.text || resp.output_text || '{}';

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {};
}

return [{
  json: {
    tema: parsed.tema || 'Controle de ponto e gestão de jornada para PMEs',
    keyword: parsed.keyword || 'control de fichaje',
    categoria: parsed.categoria || 'controle-ponto',
    intencaoBusca: parsed.intencao_busca || 'informacional',
    hoje: $('Normalizar Entrada').first().json.hoje,
  },
}];

const ai = JSON.parse($json.choices[0].message.content);
const ctx = $('Montar Prompt do Artigo').first().json;

function slugify(str) {
  return String(str)
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

const langs = ['pt', 'es', 'en'];
const t = ai.translations || {};

const title = {};
const excerpt = {};
const content_html = {};
const seo_title = {};
const seo_description = {};

for (const lang of langs) {
  const tr = t[lang] || {};
  title[lang] = tr.title || '';
  excerpt[lang] = tr.excerpt || '';
  content_html[lang] = tr.content || '';
  seo_title[lang] = tr.meta_title || '';
  seo_description[lang] = tr.meta_description || '';
}

// og_title/og_description vêm do prompt mas a API não tem esses campos (só og_image_url, que é uma URL) -- descartados de propósito.

const faq = (ai.faq || []).map((item) => ({
  question: item.question || {},
  answer: item.answer || {},
}));

const baseSlug = slugify(ai.slug || title.pt || title.es || 'post');
const slug = `${baseSlug}-${ctx.hoje}`;

return [{
  json: {
    slug,
    author: 'Equipe Jornafy',
    category: ai.category || ctx.categoria,
    status: 'draft',
    source: 'n8n',
    title,
    excerpt,
    content_html,
    seo_title,
    seo_description,
    faq,
    related_post_ids: Array.isArray(ai.related_post_ids) ? ai.related_post_ids : [],
  },
}];
